class Solution { public: int numRookCaptures(vector<vector<char>>& board){int row=0,column=0;for(int r=0;r<8;++r)for(int c=0;c<8;++c)if(board[r][c]=='R'){row=r;column=c;}int captures=0,directions[4][2]={{1,0},{-1,0},{0,1},{0,-1}};for(auto& d:directions){int r=row+d[0],c=column+d[1];while(r>=0&&r<8&&c>=0&&c<8&&board[r][c]=='.'){r+=d[0];c+=d[1];}if(r>=0&&r<8&&c>=0&&c<8&&board[r][c]=='p')++captures;}return captures;} };
